CREATE COLUMN TABLE "TEST_AP"."OFNS" ("Series" INTEGER CS_INT NOT NULL , "Name" NVARCHAR(100) NOT NULL , "PTICode" NVARCHAR(5), "FirstNum" INTEGER CS_INT, "NextNum" INTEGER CS_INT, "LastNum" INTEGER CS_INT, "Letter" NVARCHAR(1), "CAI" NVARCHAR(14), "CAIDueDate" LONGDATE CS_LONGDATE, "Remarks" NVARCHAR(100), "Locked" NVARCHAR(1) DEFAULT 'N', PRIMARY KEY ("Series")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OFNS_NAME" ON "TEST_AP"."OFNS" ( "Name" ASC )